import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { Logger, type Level } from "../src/log/logger.ts";
import type { Driver, DriverPool } from "../src/dispatch/drivers.ts";
import { requestRide, type RideRequest } from "../src/dispatch/requestRide.ts";

function capture(level: Level = "debug") {
    const lines: Record<string, any>[] = [];
    const root = new Logger(
        { write: (line) => lines.push(JSON.parse(line)) },
        { level, clock: () => new Date("2026-11-19T18:05:00Z"), bindings: { service: "dispatch", region: "lisbon" } },
    );
    return { root, lines };
}

// Pool that answers like a remote service: every call yields before returning.
function pool(drivers: Driver[], failWith?: Error): DriverPool {
    const reserved = new Set<string>();
    return {
        async nearby() {
            await tick();
            if (failWith) throw failWith;
            return drivers;
        },
        async reserve(driverId) {
            await tick();
            if (reserved.has(driverId)) return false;
            reserved.add(driverId);
            return true;
        },
    };
}

const ride = (n: number): RideRequest => ({ requestId: `req-${n}`, riderId: `rider-${n}`, rideId: `ride-${n}`, pickup: { lat: 38.7223, lng: -9.1393 } });
const driver = (id: string, lat: number): Driver => ({ id, location: { lat, lng: -9.1393 }, available: true });

test("each line is one JSON object with time, level, message, bindings and fields", () => {
    const { root, lines } = capture();
    root.info("shift started", { driversOnline: 412 });
    assert.deepEqual(lines, [{ time: "2026-11-19T18:05:00.000Z", level: "info", msg: "shift started", service: "dispatch", region: "lisbon", driversOnline: 412 }]);
});

test("lines below the configured level are dropped", async () => {
    const { root, lines } = capture("info");
    await requestRide(root, pool([driver("d1", 38.73)]), ride(1));
    assert.deepEqual(lines.map((l) => l.msg), ["ride requested", "driver assigned"]);
});

test("a failed dispatch logs the error's type and message", async () => {
    const { root, lines } = capture();
    await assert.rejects(requestRide(root, pool([], new TypeError("geo index unavailable")), ride(1)));
    const line = lines.find((l) => l.level === "error");
    assert.equal(line?.err.type, "TypeError");
    assert.equal(line?.err.message, "geo index unavailable");
    assert.equal(line?.rideId, "ride-1");
});

test("context added for one request doesn't show up on the service's own lines", async () => {
    const { root, lines } = capture();
    await requestRide(root, pool([driver("d1", 38.73)]), ride(1));
    root.info("heartbeat");
    const heartbeat = lines.at(-1)!;
    console.log("heartbeat line after one ride:", heartbeat);
    assert.equal(heartbeat.rideId, undefined);
    assert.equal(heartbeat.requestId, undefined);
});

test("two rides dispatched at the same time each log under their own ids", async () => {
    const { root, lines } = capture();
    const drivers = pool([driver("d1", 38.73), driver("d2", 38.74)]);
    await Promise.all([requestRide(root, drivers, ride(1)), requestRide(root, drivers, ride(2))]);
    const assigned = lines.filter((l) => l.msg === "driver assigned").map((l) => [l.requestId, l.rideId, l.riderId, l.driverId]);
    assert.deepEqual(assigned.sort(), [["req-1", "ride-1", "rider-1", "d1"], ["req-2", "ride-2", "rider-2", "d2"]]);
    for (const l of lines) assert.equal(l.rideId?.slice(5), l.requestId?.slice(4), `mixed ids on "${l.msg}"`);
});

test("when nobody is free the rider's request is logged as a warning", async () => {
    const { root, lines } = capture();
    const result = await requestRide(root, pool([{ ...driver("d1", 38.73), available: false }]), ride(7));
    assert.deepEqual(result, { status: "no_driver" });
    const warn = lines.find((l) => l.level === "warn");
    assert.deepEqual([warn?.msg, warn?.requestId, warn?.radiusKm, warn?.candidates], ["no driver available", "req-7", 5, 0]);
});

test("fields can't overwrite time, level or msg, and undefined fields are left out", () => {
    const { root, lines } = capture();
    root.child({ level: "fatal" }).warn("surge pricing on", { msg: "spoofed", time: "yesterday", zone: "baixa", note: undefined });
    assert.deepEqual(lines[0], { time: "2026-11-19T18:05:00.000Z", level: "warn", msg: "surge pricing on", service: "dispatch", region: "lisbon", zone: "baixa" });
});
